/* Streamdown's built-in components (chat code blocks with their copy button,
   etc.) carry Tailwind classes inside its dist bundle; without scanning it,
   those classes are never generated and the blocks render unstyled. */
@source "../../../../node_modules/streamdown/dist/*.js";

/* Marketing display face. `font-display` resolves to Host Grotesk (loaded by
   next/font in the root layout as --font-host-grotesk) and is used only on
   marketing/product-page headings; the app dashboard stays on Inter. */
@theme inline {
	--font-display: var(--font-host-grotesk);
}

/* Shiki dual-theme (github-light / vesper). CodeBlock highlights with
   defaultColor:false, so each token carries both --shiki-light and
   --shiki-dark (+ *-bg); the .dark class selects which to use. */
.shiki {
	background-color: var(--shiki-light-bg);
}
.shiki,
.shiki span {
	color: var(--shiki-light);
}
.dark .shiki {
	background-color: var(--shiki-dark-bg);
}
.dark .shiki,
.dark .shiki span {
	color: var(--shiki-dark);
}

/* Crisp 1px inner outline on top of any surface (theme-aware). */
.border-overlay {
	outline: 1px solid rgba(0, 0, 0, 0.1);
	outline-offset: -1px;
}
.dark .border-overlay {
	outline-color: rgba(255, 255, 255, 0.1);
}

/* Match the light inset's exact three-layer geometry while Foggy is carved
   into the bottom edge. Only the colors change for dark mode: a faint light
   perimeter plus compact dark depth, with the same 0 / 0.5 / 1px offsets.
   Set as box-shadow on the inset itself, since redefining --custom-shadow here
   would cascade into every descendant using the var (page-header icon tiles,
   cards), splitting them from their siblings outside the panel. */
.dark .foggy-inset-closed {
	box-shadow: 0 0 0 0.5px rgba(255, 255, 255, 0.09), 0 0.5px 2px -0.5px
		rgba(0, 0, 0, 0.24), 0 1px 4px 0 rgba(0, 0, 0, 0.16);
}

/* Poster map edge pulses, CSS-driven so dozens of edges don't each run a JS
   animation loop. Offset matches the "4 156" dash pattern (one period = 160). */
@keyframes poster-pulse {
	to {
		stroke-dashoffset: -160;
	}
}
@keyframes poster-fade {
	to {
		opacity: 1;
	}
}

/* Page entrance, opacity-only fade, played once per hard load (gated by a
   module-scope flag at the call site, Linear-style): client-side navigations
   back to the page render instantly. */
@keyframes page-fade-in {
	from {
		opacity: 0;
	}
}
.page-fade-in {
	animation: page-fade-in 75ms ease-out;
}
@media (prefers-reduced-motion: reduce) {
	.page-fade-in {
		animation: none;
	}
}

/* Marketing fog drift, CSS keyframes instead of JS-driven Motion so the
   transform animates on the compositor: the blurred/masked layers rasterize
   once and only their transforms change, keeping the main thread free (the
   JS version made every hover on the page feel laggy). will-change pins the
   layer; translate percentages are relative to the (oversized) layer. */
@keyframes fog-drift-a {
	0%,
	100% {
		transform: translate(-3%, -2%);
	}
	50% {
		transform: translate(4%, 2%);
	}
}
@keyframes fog-drift-b {
	0%,
	100% {
		transform: translate(3%, 2%);
	}
	50% {
		transform: translate(-4%, -3%);
	}
}
@keyframes fog-drift-c {
	0%,
	100% {
		transform: translate(-2%, 3%);
	}
	50% {
		transform: translate(3%, -2%);
	}
}
@keyframes fog-drift-d {
	0%,
	100% {
		transform: translate(2%, -2%);
	}
	50% {
		transform: translate(-3%, 3%);
	}
}
@keyframes fog-drift-e {
	0%,
	100% {
		transform: translate(-2%, 1%);
	}
	50% {
		transform: translate(2%, -2%);
	}
}
@keyframes fog-drift-footer {
	0%,
	100% {
		transform: translate(-3%, -10%);
	}
	50% {
		transform: translate(3%, 10%);
	}
}
.fog-layer {
	will-change: transform;
	animation-timing-function: ease-in-out;
	animation-iteration-count: infinite;
}
@media (prefers-reduced-motion: reduce) {
	.fog-layer {
		animation: none;
	}
}

/* Start each agent's BorderBeam at a random point in its spin cycle. The
   library starts every beam's `beam-spin` animation at phase 0 on mount, so
   agents revolve in lockstep; a per-node negative delay (set inline as
   --beam-phase) scatters them. Two values: first for beam-spin, second keeps
   the fade-in animation undelayed. */
.agent-beam [data-beam][data-active],
.agent-beam[data-beam][data-active] {
	animation-delay: var(--beam-phase, 0s), 0s;
}

/* Footer cutting mat: the single highlighted dash on each brand circle walks
   the ring one dash at a time. The ring is normalized to pathLength 360 with a
   10-unit dash period, so 36 steps of -360 land exactly on the next dash. */
@keyframes mat-dash {
	to {
		stroke-dashoffset: -360;
	}
}
.mat-dash {
	animation: mat-dash 4.8s steps(36, end) infinite;
}
@media (prefers-reduced-motion: reduce) {
	.mat-dash {
		animation: none;
	}
}
